193→// collectPerfEntries reads a JSONL log file and returns the last N perf entries,
194→// ordered newest first. If hookFilter is non-empty, only entries with a matching
195→// Op field are included.
196→func collectPerfEntries(logFile string, last int, hookFilter string) ([]perfEntry, error) {
197→	f, err := os.Open(logFile) //nolint:gosec // logFile is a CLI-resolved path, not user-supplied input
198→	if err != nil {
199→		if errors.Is(err, os.ErrNotExist) {
200→			return nil, nil
201→		}
202→		return nil, fmt.Errorf("opening perf log: %w", err)
203→	}
204→	defer f.Close()
205→
206→	var entries []perfEntry
207→
208→	scanner := bufio.NewScanner(f)
209→	for scanner.Scan() {
210→		entry := parsePerfEntry(scanner.Text())
211→		if entry == nil {
212→			continue
213→		}
214→		if hookFilter != "" && entry.Op != hookFilter {
215→			continue
216→		}
217→		entries = append(entries, *entry)
218→	}
219→
220→	if err := scanner.Err(); err != nil {
221→		return nil, fmt.Errorf("reading perf log: %w", err)
222→	}
223→
224→	// Take the last N entries
225→	if len(entries) > last {
226→		entries = entries[len(entries)-last:]
227→	}
228→
229→	// Reverse so newest entries are first
230→	for i, j := 0, len(entries)-1; i < j; i, j = i+1, j-1 {
231→		entries[i], entries[j] = entries[j], entries[i]
232→	}
233→
234→	return entries, nil
235→}
