237→// renderPerfEntries writes a formatted table of perf entries to w.
238→// If entries is empty, it prints a help message about enabling perf traces.
239→func renderPerfEntries(w io.Writer, entries []perfEntry) {
240→	if len(entries) == 0 {
241→		fmt.Fprintln(w, "No perf entries found.")
242→		fmt.Fprintln(w, `Perf traces are logged at DEBUG level. Make sure ENTIRE_LOG_LEVEL=DEBUG is set`)
243→		fmt.Fprintln(w, `in your shell profile, or set log_level to "DEBUG" in .entire/settings.json.`)
244→		return
245→	}
246→
247→	for i, entry := range entries {
248→		if i > 0 {
249→			fmt.Fprintln(w)
250→		}
251→
252→		// Header line: op  duration  [timestamp]
253→		header := fmt.Sprintf("%s  %dms", entry.Op, entry.DurationMs)
254→		if !entry.Time.IsZero() {
255→			header += "  " + entry.Time.Format(time.RFC3339)
256→		}
257→		fmt.Fprintln(w, header)
258→		fmt.Fprintln(w)
259→
260→		if len(entry.Steps) == 0 {
261→			continue
262→		}
263→
264→		// Compute max name display width (at least len("STEP")).
265→		// Sub-steps are indented 5 extra display columns relative to parent rows
266→		// ("    " + "├─ " = 7 display cols vs "  " = 2 display cols).
267→		const subExtraIndent = 5
268→		nameWidth := len("STEP")
269→		for _, s := range entry.Steps {
270→			if len(s.Name) > nameWidth {
271→				nameWidth = len(s.Name)
272→			}
273→			for _, sub := range s.SubSteps {
274→				if needed := len(sub.Name) + subExtraIndent; needed > nameWidth {
275→					nameWidth = needed
276→				}
277→			}
278→		}
279→
280→		// Column header
281→		fmt.Fprintf(w, "  %-*s  %8s\n", nameWidth, "STEP", "DURATION")
282→
283→		// Step rows
284→		for _, s := range entry.Steps {
285→			dur := fmt.Sprintf("%dms", s.DurationMs)
286→			line := fmt.Sprintf("  %-*s  %8s", nameWidth, s.Name, dur)
287→			if s.Error {
288→				line += "  x"
289→			}
290→			fmt.Fprintln(w, line)
291→
292→			// Sub-step rows with ASCII tree connectors.
293→			// Pad manually to avoid multi-byte UTF-8 box-drawing chars
294→			// (├─, └─) breaking Go's byte-based %-*s alignment.
295→			for i, sub := range s.SubSteps {
296→				connector := "├─"
297→				if i == len(s.SubSteps)-1 {
298→					connector = "└─"
299→				}
300→				subDur := fmt.Sprintf("%dms", sub.DurationMs)
301→				pad := nameWidth - subExtraIndent - len(sub.Name)
302→				if pad < 0 {
303→					pad = 0
304→				}
305→				subLine := fmt.Sprintf("    %s %s%s  %8s", connector, sub.Name, strings.Repeat(" ", pad), subDur)
306→				if sub.Error {
307→					subLine += "  x"
308→				}
309→				fmt.Fprintln(w, subLine)
310→			}
311→		}
312→	}
313→}
