173→func TestRenderPerfEntries(t *testing.T) {
174→	t.Parallel()
175→
176→	entries := []perfEntry{
177→		{
178→			Op:         "post-commit",
179→			DurationMs: 250,
180→			Time:       time.Date(2026, 1, 15, 10, 30, 0, 0, time.UTC),
181→			Steps: []perfStep{
182→				{Name: "load_session", DurationMs: 50, Error: false},
183→				{Name: "save_checkpoint", DurationMs: 80, Error: true},
184→				{Name: "condense", DurationMs: 120, Error: false},
185→			},
186→		},
187→	}
188→
189→	var buf bytes.Buffer
190→	renderPerfEntries(&buf, entries)
191→	out := buf.String()
192→
193→	// Verify header contains op name, total duration, and timestamp
194→	if !strings.Contains(out, "post-commit") {
195→		t.Errorf("output missing op name 'post-commit':\n%s", out)
196→	}
197→	if !strings.Contains(out, "250ms") {
198→		t.Errorf("output missing total duration '250ms':\n%s", out)
199→	}
200→	if !strings.Contains(out, "2026-01-15T10:30:00Z") {
201→		t.Errorf("output missing RFC3339 timestamp:\n%s", out)
202→	}
203→
204→	// Verify step names and durations appear
205→	if !strings.Contains(out, "load_session") {
206→		t.Errorf("output missing step name 'load_session':\n%s", out)
207→	}
208→	if !strings.Contains(out, "50ms") {
209→		t.Errorf("output missing step duration '50ms':\n%s", out)
210→	}
211→	if !strings.Contains(out, "save_checkpoint") {
212→		t.Errorf("output missing step name 'save_checkpoint':\n%s", out)
213→	}
214→	if !strings.Contains(out, "80ms") {
215→		t.Errorf("output missing step duration '80ms':\n%s", out)
216→	}
217→	if !strings.Contains(out, "condense") {
218→		t.Errorf("output missing step name 'condense':\n%s", out)
219→	}
220→	if !strings.Contains(out, "120ms") {
221→		t.Errorf("output missing step duration '120ms':\n%s", out)
222→	}
223→
224→	// Verify column header
225→	if !strings.Contains(out, "STEP") {
226→		t.Errorf("output missing column header 'STEP':\n%s", out)
227→	}
228→	if !strings.Contains(out, "DURATION") {
229→		t.Errorf("output missing column header 'DURATION':\n%s", out)
230→	}
231→
232→	// Verify error marker on the errored step line
233→	lines := strings.Split(out, "\n")
234→	foundErrorMarker := false
235→	for _, line := range lines {
236→		if strings.Contains(line, "save_checkpoint") && strings.Contains(line, "x") {
237→			foundErrorMarker = true
238→			break
239→		}
240→	}
241→	if !foundErrorMarker {
242→		t.Errorf("output missing error marker 'x' on save_checkpoint line:\n%s", out)
243→	}
244→}
