246→func TestParsePerfEntry_WithSubSteps(t *testing.T) {
247→	t.Parallel()
248→
249→	line := `{"time":"2026-01-15T10:30:00Z","level":"DEBUG","msg":"perf","op":"post-commit","duration_ms":350,"steps.process_sessions_ms":300,"steps.process_sessions.0_ms":100,"steps.process_sessions.1_ms":200,"steps.process_sessions.1_err":true,"steps.cleanup_ms":50}`
250→
251→	entry := parsePerfEntry(line)
252→	if entry == nil {
253→		t.Fatal("parsePerfEntry returned nil")
254→	}
255→
256→	if len(entry.Steps) != 2 {
257→		t.Fatalf("len(Steps) = %d, want 2", len(entry.Steps))
258→	}
259→
260→	// Steps sorted alphabetically: cleanup, process_sessions
261→	if entry.Steps[0].Name != "cleanup" {
262→		t.Errorf("Steps[0].Name = %q, want %q", entry.Steps[0].Name, "cleanup")
263→	}
264→	if len(entry.Steps[0].SubSteps) != 0 {
265→		t.Errorf("Steps[0] should have no sub-steps, got %d", len(entry.Steps[0].SubSteps))
266→	}
267→
268→	ps := entry.Steps[1]
269→	if ps.Name != "process_sessions" {
270→		t.Errorf("Steps[1].Name = %q, want %q", ps.Name, "process_sessions")
271→	}
272→	if ps.DurationMs != 300 {
