  1→package perf
  2→
  3→import (
  4→	"context"
  5→	"fmt"
  6→	"log/slog"
  7→	"time"
  8→
  9→	"github.com/entireio/cli/cmd/entire/cli/logging"
 10→)
 11→
 12→// Span tracks timing for an operation and its substeps.
 13→// A Span is not safe for concurrent use from multiple goroutines.
 14→type Span struct {
 15→	name     string
 16→	start    time.Time
 17→	parent   *Span
 18→	children []*Span
 19→	duration time.Duration
 20→	attrs    []slog.Attr
 21→	ctx      context.Context
 22→	ended    bool
 23→	err      error
 24→}
 25→
 26→// Start begins a new span. If ctx already has a span, the new one becomes a child.
 27→// Returns the updated context and the span. Call span.End() when the operation completes.
 28→func Start(ctx context.Context, name string, attrs ...slog.Attr) (context.Context, *Span) {
 29→	parent := spanFromContext(ctx)
 30→	s := &Span{
 31→		name:   name,
 32→		start:  time.Now(),
 33→		parent: parent,
 34→		attrs:  attrs,
 35→		ctx:    ctx,
 36→	}
 37→	if parent != nil {
 38→		parent.children = append(parent.children, s)
 39→	}
 40→	return contextWithSpan(ctx, s), s
 41→}
 42→
 43→// RecordError marks the span as errored. Only the first non-nil error is stored;
 44→// subsequent calls are no-ops. Call this before End() on error paths.
 45→func (s *Span) RecordError(err error) {
 46→	if err == nil || s.err != nil {
 47→		return
 48→	}
 49→	s.err = err
 50→}
 51→
 52→// End completes the span. For root spans, emits a single DEBUG log line
 53→// with the full timing tree. For child spans, records the duration only.
 54→// Safe to call multiple times -- subsequent calls are no-ops.
 55→func (s *Span) End() {
 56→	if s.ended {
 57→		return
 58→	}
 59→	s.ended = true
 60→	s.duration = time.Since(s.start)
 61→
 62→	// Only root spans emit log output
 63→	if s.parent != nil {
 64→		return
 65→	}
 66→
 67→	// Build log attributes: op, duration_ms, error flag, then child step durations.
 68→	// Component is set via context so it appears exactly once in the log line.
 69→	logCtx := logging.WithComponent(s.ctx, "perf")
 70→	attrs := make([]any, 0, 3+2*len(s.children)+len(s.attrs))
 71→	attrs = append(attrs, slog.String("op", s.name))
 72→	attrs = append(attrs, slog.Int64("duration_ms", s.duration.Milliseconds()))
 73→	if s.err != nil {
 74→		attrs = append(attrs, slog.Bool("error", true))
 75→	}
 76→
 77→	// Add child step durations (and error flags) as flat keys.
 78→	// Disambiguate duplicate child names (from loops) with .1, .2, etc. suffixes
 79→	// to prevent later values from overwriting earlier ones in JSON output.
 80→	//
 81→	// Group spans (children that have their own children) also emit grandchildren
 82→	// with 0-based indexing: steps.<name>.0_ms, steps.<name>.1_ms, etc.
 83→	seen := make(map[string]int, len(s.children))
 84→	for _, child := range s.children {
 85→		// Auto-end children that were not explicitly ended
 86→		if !child.ended {
 87→			child.End()
 88→		}
 89→		stepKey := childStepKey(child.name, seen)
 90→		key := fmt.Sprintf("steps.%s_ms", stepKey)
 91→		attrs = append(attrs, slog.Int64(key, child.duration.Milliseconds()))
 92→		if child.err != nil {
 93→			errKey := fmt.Sprintf("steps.%s_err", stepKey)
 94→			attrs = append(attrs, slog.Bool(errKey, true))
 95→		}
 96→
 97→		// Emit grandchildren (group iterations) with 0-based indexing
 98→		for i, gc := range child.children {
 99→			if !gc.ended {
100→				gc.End()
101→			}
102→			gcKey := fmt.Sprintf("steps.%s.%d_ms", stepKey, i)
103→			attrs = append(attrs, slog.Int64(gcKey, gc.duration.Milliseconds()))
104→			if gc.err != nil {
105→				gcErrKey := fmt.Sprintf("steps.%s.%d_err", stepKey, i)
106→				attrs = append(attrs, slog.Bool(gcErrKey, true))
107→			}
108→		}
109→	}
110→
111→	// Add any extra attributes from Start()
112→	for _, a := range s.attrs {
113→		attrs = append(attrs, a)
114→	}
115→
116→	logging.Debug(logCtx, "perf", attrs...)
117→}
118→
119→// childStepKey returns a unique key for a child span name.
120→// First occurrence keeps the original name; subsequent get .1, .2, etc.
121→// The seen map is updated in place.
122→func childStepKey(name string, seen map[string]int) string {
123→	n := seen[name]
124→	seen[name] = n + 1
125→	if n == 0 {
126→		return name
127→	}
128→	return fmt.Sprintf("%s.%d", name, n)
129→}
130→
131→// LoopSpan wraps a Span that groups loop iterations. Each call to Iteration
132→// creates a child span representing one pass through the loop.
133→//
134→// Usage:
135→//
136→//	ctx, loop := perf.StartLoop(ctx, "process_sessions")
137→//	for _, item := range items {
138→//	    iterCtx, iterSpan := loop.Iteration(ctx)
139→//	    doWork(iterCtx, item)
140→//	    iterSpan.End()
141→//	}
142→//	loop.End()
143→type LoopSpan struct {
144→	span *Span
145→}
146→
147→// StartLoop begins a new loop span. The returned context contains the loop span
148→// and should be passed to Iteration. Call loop.End() after the loop completes.
149→func StartLoop(ctx context.Context, name string, attrs ...slog.Attr) (context.Context, *LoopSpan) {
150→	ctx, s := Start(ctx, name, attrs...)
151→	return ctx, &LoopSpan{span: s}
152→}
153→
154→// Iteration creates a child span for a single loop iteration. The caller must
155→// call End() on the returned span when the iteration completes.
156→func (l *LoopSpan) Iteration(ctx context.Context) (context.Context, *Span) {
157→	return Start(ctx, l.span.name)
158→}
159→
160→// End completes the loop span by ending the underlying span.
161→// Note: this does not itself iterate over and end unended iteration spans;
162→// any automatic cleanup of child spans occurs when the root span is ended.
163→func (l *LoopSpan) End() {
164→	l.span.End()
165→}
