  1→package cli
  2→
  3→import (
  4→	"bufio"
  5→	"encoding/json"
  6→	"errors"
  7→	"fmt"
  8→	"io"
  9→	"os"
 10→	"sort"
 11→	"strconv"
 12→	"strings"
 13→	"time"
 14→)
 15→
 16→// perfStep represents a single timed step within a perf span.
 17→// Group steps (from nested spans) have SubSteps with 0-based iteration numbering.
 18→type perfStep struct {
 19→	Name       string
 20→	DurationMs int64
 21→	Error      bool
 22→	SubSteps   []perfStep
 23→}
 24→
 25→// perfEntry represents a parsed performance trace log entry.
 26→type perfEntry struct {
 27→	Op         string
 28→	DurationMs int64
 29→	Error      bool
 30→	Time       time.Time
 31→	Steps      []perfStep
 32→}
 33→
 34→// parsePerfEntry parses a JSON log line into a perfEntry.
 35→// Returns nil if the line is not valid JSON or is not a perf entry (msg != "perf").
 36→func parsePerfEntry(line string) *perfEntry {
 37→	var raw map[string]json.RawMessage
 38→	if err := json.Unmarshal([]byte(line), &raw); err != nil {
 39→		return nil
 40→	}
 41→
 42→	// Check that msg == "perf"
 43→	var msg string
 44→	if msgRaw, ok := raw["msg"]; !ok {
 45→		return nil
 46→	} else if err := json.Unmarshal(msgRaw, &msg); err != nil || msg != "perf" {
 47→		return nil
 48→	}
 49→
 50→	entry := &perfEntry{}
 51→
 52→	// Extract op
 53→	if opRaw, ok := raw["op"]; ok {
 54→		if err := json.Unmarshal(opRaw, &entry.Op); err != nil {
 55→			return nil
 56→		}
 57→	}
 58→
 59→	// Extract duration_ms
 60→	if dRaw, ok := raw["duration_ms"]; ok {
 61→		if err := json.Unmarshal(dRaw, &entry.DurationMs); err != nil {
 62→			return nil
 63→		}
 64→	}
 65→
 66→	// Extract error flag
 67→	if errRaw, ok := raw["error"]; ok {
 68→		if err := json.Unmarshal(errRaw, &entry.Error); err != nil {
 69→			return nil
 70→		}
 71→	}
 72→
 73→	// Extract time
 74→	if tRaw, ok := raw["time"]; ok {
 75→		var ts string
 76→		if err := json.Unmarshal(tRaw, &ts); err == nil {
 77→			if parsed, err := time.Parse(time.RFC3339, ts); err == nil {
 78→				entry.Time = parsed
 79→			}
 80→		}
 81→	}
 82→
 83→	// Extract steps by finding keys matching "steps.*_ms"
 84→	stepDurations := make(map[string]int64)
 85→	stepErrors := make(map[string]bool)
 86→
 87→	for key, val := range raw {
 88→		if strings.HasPrefix(key, "steps.") && strings.HasSuffix(key, "_ms") {
 89→			name := strings.TrimPrefix(key, "steps.")
 90→			name = strings.TrimSuffix(name, "_ms")
 91→
 92→			var ms int64
 93→			if err := json.Unmarshal(val, &ms); err == nil {
 94→				stepDurations[name] = ms
 95→			}
 96→		} else if strings.HasPrefix(key, "steps.") && strings.HasSuffix(key, "_err") {
 97→			name := strings.TrimPrefix(key, "steps.")
 98→			name = strings.TrimSuffix(name, "_err")
 99→
100→			var errFlag bool
101→			if err := json.Unmarshal(val, &errFlag); err == nil {
102→				stepErrors[name] = errFlag
103→			}
104→		}
105→	}
106→
107→	// Separate parent steps from sub-steps.
108→	// A key like "foo.0" is a sub-step of "foo" if "foo" also exists as a parent
109→	// and the last segment is a non-negative integer.
110→	subStepDurations := make(map[string]map[int]int64) // parent -> index -> ms
111→	subStepErrors := make(map[string]map[int]bool)     // parent -> index -> err
112→	parentStepDurations := make(map[string]int64)
113→	parentStepErrors := make(map[string]bool)
114→
115→	for name, ms := range stepDurations {
116→		if parent, idx, ok := parseSubStepKey(name, stepDurations); ok {
117→			if subStepDurations[parent] == nil {
118→				subStepDurations[parent] = make(map[int]int64)
119→			}
120→			subStepDurations[parent][idx] = ms
121→			if stepErrors[name] {
122→				if subStepErrors[parent] == nil {
123→					subStepErrors[parent] = make(map[int]bool)
124→				}
125→				subStepErrors[parent][idx] = true
126→			}
127→		} else {
128→			parentStepDurations[name] = ms
129→			parentStepErrors[name] = stepErrors[name]
130→		}
131→	}
132→
133→	// Build steps slice sorted alphabetically by name
134→	steps := make([]perfStep, 0, len(parentStepDurations))
135→	for name, ms := range parentStepDurations {
136→		step := perfStep{
137→			Name:       name,
138→			DurationMs: ms,
139→			Error:      parentStepErrors[name],
140→		}
141→
142→		// Attach sub-steps if any, sorted by numeric index
143→		if subs, ok := subStepDurations[name]; ok {
144→			indices := make([]int, 0, len(subs))
145→			for idx := range subs {
146→				indices = append(indices, idx)
147→			}
148→			sort.Ints(indices)
149→
150→			subList := make([]perfStep, 0, len(subs))
151→			for _, idx := range indices {
152→				subList = append(subList, perfStep{
153→					Name:       fmt.Sprintf("%s.%d", name, idx),
154→					DurationMs: subs[idx],
155→					Error:      subStepErrors[name][idx],
156→				})
157→			}
158→			step.SubSteps = subList
159→		}
160→
161→		steps = append(steps, step)
162→	}
163→	sort.Slice(steps, func(i, j int) bool {
164→		return steps[i].Name < steps[j].Name
165→	})
166→
167→	entry.Steps = steps
168→
169→	return entry
170→}
171→
172→// parseSubStepKey checks if a step name like "foo.0" is a sub-step of "foo".
173→// Returns the parent name, index, and true if it is a sub-step.
174→// A name is a sub-step if: the last segment after the final "." is a non-negative
175→// integer AND the parent name exists in allSteps.
176→func parseSubStepKey(name string, allSteps map[string]int64) (string, int, bool) {
177→	lastDot := strings.LastIndex(name, ".")
178→	if lastDot < 0 {
179→		return "", 0, false
180→	}
181→	parent := name[:lastDot]
182→	suffix := name[lastDot+1:]
183→	idx, err := strconv.Atoi(suffix)
184→	if err != nil || idx < 0 {
185→		return "", 0, false
186→	}
187→	if _, exists := allSteps[parent]; !exists {
188→		return "", 0, false
189→	}
190→	return parent, idx, true
191→}
192→
193→// collectPerfEntries reads a JSONL log file and returns the last N perf entries,
194→// ordered newest first. If hookFilter is non-empty, only entries with a matching
195→// Op field are included.
196→func collectPerfEntries(logFile string, last int, hookFilter string) ([]perfEntry, error) {
197→	f, err := os.Open(logFile) //nolint:gosec // logFile is a CLI-resolved path, not user-supplied input
198→	if err != nil {
199→		if errors.Is(err, os.ErrNotExist) {
200→			return nil, nil
201→		}
202→		return nil, fmt.Errorf("opening perf log: %w", err)
203→	}
204→	defer f.Close()
205→
206→	var entries []perfEntry
207→
208→	scanner := bufio.NewScanner(f)
209→	for scanner.Scan() {
210→		entry := parsePerfEntry(scanner.Text())
211→		if entry == nil {
212→			continue
213→		}
214→		if hookFilter != "" && entry.Op != hookFilter {
215→			continue
216→		}
217→		entries = append(entries, *entry)
218→	}
219→
220→	if err := scanner.Err(); err != nil {
221→		return nil, fmt.Errorf("reading perf log: %w", err)
222→	}
223→
224→	// Take the last N entries
225→	if len(entries) > last {
226→		entries = entries[len(entries)-last:]
227→	}
228→
229→	// Reverse so newest entries are first
230→	for i, j := 0, len(entries)-1; i < j; i, j = i+1, j-1 {
231→		entries[i], entries[j] = entries[j], entries[i]
232→	}
233→
234→	return entries, nil
235→}
236→
237→// renderPerfEntries writes a formatted table of perf entries to w.
238→// If entries is empty, it prints a help message about enabling perf traces.
239→func renderPerfEntries(w io.Writer, entries []perfEntry) {
240→	if len(entries) == 0 {
241→		fmt.Fprintln(w, "No perf entries found.")
242→		fmt.Fprintln(w, `Perf traces are logged at DEBUG level. Make sure ENTIRE_LOG_LEVEL=DEBUG is set`)
243→		fmt.Fprintln(w, `in your shell profile, or set log_level to "DEBUG" in .entire/settings.json.`)
244→		return
245→	}
246→
247→	for i, entry := range entries {
248→		if i > 0 {
249→			fmt.Fprintln(w)
250→		}
251→
252→		// Header line: op  duration  [timestamp]
253→		header := fmt.Sprintf("%s  %dms", entry.Op, entry.DurationMs)
254→		if !entry.Time.IsZero() {
255→			header += "  " + entry.Time.Format(time.RFC3339)
256→		}
257→		fmt.Fprintln(w, header)
258→		fmt.Fprintln(w)
259→
260→		if len(entry.Steps) == 0 {
261→			continue
262→		}
263→
264→		// Compute max name display width (at least len("STEP")).
265→		// Sub-steps are indented 5 extra display columns relative to parent rows
266→		// ("    " + "├─ " = 7 display cols vs "  " = 2 display cols).
267→		const subExtraIndent = 5
268→		nameWidth := len("STEP")
269→		for _, s := range entry.Steps {
270→			if len(s.Name) > nameWidth {
271→				nameWidth = len(s.Name)
272→			}
273→			for _, sub := range s.SubSteps {
274→				if needed := len(sub.Name) + subExtraIndent; needed > nameWidth {
275→					nameWidth = needed
276→				}
277→			}
278→		}
279→
280→		// Column header
281→		fmt.Fprintf(w, "  %-*s  %8s\n", nameWidth, "STEP", "DURATION")
282→
283→		// Step rows
284→		for _, s := range entry.Steps {
285→			dur := fmt.Sprintf("%dms", s.DurationMs)
286→			line := fmt.Sprintf("  %-*s  %8s", nameWidth, s.Name, dur)
287→			if s.Error {
288→				line += "  x"
289→			}
290→			fmt.Fprintln(w, line)
291→
292→			// Sub-step rows with ASCII tree connectors.
293→			// Pad manually to avoid multi-byte UTF-8 box-drawing chars
294→			// (├─, └─) breaking Go's byte-based %-*s alignment.
295→			for i, sub := range s.SubSteps {
296→				connector := "├─"
297→				if i == len(s.SubSteps)-1 {
298→					connector = "└─"
299→				}
300→				subDur := fmt.Sprintf("%dms", sub.DurationMs)
301→				pad := nameWidth - subExtraIndent - len(sub.Name)
302→				if pad < 0 {
303→					pad = 0
304→				}
305→				subLine := fmt.Sprintf("    %s %s%s  %8s", connector, sub.Name, strings.Repeat(" ", pad), subDur)
306→				if sub.Error {
307→					subLine += "  x"
308→				}
309→				fmt.Fprintln(w, subLine)
310→			}
311→		}
312→	}
313→}
